from html.parser import HTMLParser
from pathlib import Path
import os, re
p=Path(os.environ['TMPDIR'])/'vgu_verify'/'ddg1.html'
s=p.read_text(errors='ignore')
class P(HTMLParser):
 def __init__(self): super().__init__(); self.href=None; self.text=[]; self.items=[]
 def handle_starttag(self,tag,attrs):
  a=dict(attrs)
  if tag=='a' and 'result__a' in a.get('class',''):
   self.href=a.get('href'); self.text=[]
 def handle_data(self,data):
  if self.href is not None: self.text.append(data)
 def handle_endtag(self,tag):
  if tag=='a' and self.href is not None:
   self.items.append((''.join(self.text).strip(),self.href)); self.href=None
p1=P(); p1.feed(s)
for x in p1.items[:15]: print(x)
PY"

